INSERT INTO cat_careers (position, title, home, what) VALUES
  (1, 'Production Operator', 'production', 'Runs production equipment on a line or in a cell: loads material, starts and watches the machine, checks the product and keeps count. The entry job in most plants.'),
  (2, 'Setup Technician', 'production', 'Changes production machines over from one job to the next: installs the tooling, die or mold, sets the machine, runs the first parts and gets them approved before operators take over.'),
  (3, 'Continuous Improvement Specialist', 'production', 'Leads lean work on the floor: maps a process, runs kaizen events, sets standard work and 5S, and follows the numbers to see that the gain holds.'),
  (4, 'Industrial Engineer', 'production', 'Designs how work flows through a plant: studies times and motions, balances lines, lays out stations and material flow, and measures output and losses.'),
  (5, 'CNC Machine Operator', 'machining', 'Runs CNC mills and lathes that a machinist has set up: loads parts, starts the cycle, measures what comes off and adjusts offsets to hold size.'),
  (6, 'CNC Machinist', 'machining', 'Sets up and runs CNC mills and lathes to make precision parts from a print: chooses workholding and tools, sets offsets, proves out the program and holds tolerance. Can also cut on manual machines.'),
  (7, 'Swiss CNC Machinist', 'machining', 'Sets up and runs Swiss-type sliding-headstock lathes that turn small, long precision parts from bar, typically for medical devices, connectors and aerospace fittings.'),
  (8, 'CNC Programmer', 'machining', 'Writes the programs CNC machines run: plans the operations, builds toolpaths in CAM software, edits G-code, simulates the cut and proves the program out with the machinist.'),
  (9, 'Precision Grinder', 'machining', 'Grinds hardened parts to final size and finish on surface, cylindrical and internal grinders, dressing the wheel and measuring to tenths of a thousandth.'),
  (10, 'EDM Operator', 'machining', 'Cuts hardened steel and carbide with electrical discharge machines, wire and sinker, for die details, mold cavities and shapes a cutter cannot reach.'),
  (11, 'Tool and Die Maker', 'machining', 'Builds, fits and repairs the dies, molds, gauges and precision tooling a plant produces with: machines and grinds the details, fits them together and tries the tool out in the press.'),
  (12, 'Jig and Fixture Builder', 'machining', 'Builds the jigs, fixtures, templates and layup tools that hold parts while they are drilled, assembled or cured, then sets and certifies them to the engineering datums.'),
  (13, 'Sawmill Operator', 'machining', 'Runs the stations that turn logs into lumber: the head rig and canter, edgers, gangs and trimmers, the sorter and stacker, the dry kilns and the planer. Saws for the most value from each log, mostly from a booth with scanners and optimizers.'),
  (14, 'Saw Filer', 'machining', 'Keeps a sawmill''s band and circular saws cutting straight: grinds, swages and tips the teeth, and levels and tensions the blades on the bench. The skilled trade of the mill''s filing room.'),
  (15, 'Woodworking Machine Operator', 'machining', 'Sets up and runs the machines of a wood plant (panel saws, CNC routers, edgebanders, moulders and wide-belt sanders), cutting and shaping parts for cabinets, furniture, doors and millwork.'),
  (16, 'MIG Welder', 'fabrication', 'Welds steel and aluminum parts with the MIG process on a production line or in a fabrication shop, fitting the joint, setting the machine and checking each weld by eye.'),
  (17, 'Welder', 'fabrication', 'Joins metal with several processes (stick, MIG, flux-cored, TIG) in all positions, on structural steel, pipe and plate, and holds the performance qualifications the work calls for.'),
  (18, 'TIG Welder', 'fabrication', 'Makes precise TIG welds on thin and exotic metals (stainless, aluminum, titanium) where appearance and soundness both matter: tube, sheet, fittings and repair work.'),
  (19, 'Aerospace Welder', 'fabrication', 'Welds flight hardware to aerospace codes: propellant tanks, pressure vessels, ducts and tubing in aluminum-lithium, stainless and titanium, by manual TIG, orbital and automated processes.'),
  (20, 'Robotic Welding Technician', 'fabrication', 'Runs and tends robotic welding cells: loads fixtures, touches up weld paths on the teach pendant, changes tips and wire, and checks welds against the standard.'),
  (21, 'Laser Welding Technician', 'fabrication', 'Sets up and runs laser welding and brazing systems, checks the seam by section and test, and keeps the optics and process in window.'),
  (22, 'Body Weld Technician', 'fabrication', 'Works in an automotive body shop joining stamped panels into a body: tends spot-weld robots and guns, applies adhesive, dresses tips and tears down welds to prove them.'),
  (23, 'Sheet Metal Fabricator', 'fabrication', 'Makes parts and enclosures from sheet: lays out the flat pattern, cuts it, forms it on a press brake and joins it by spot weld, rivet or weld.'),
  (24, 'Metal Fabricator', 'fabrication', 'Builds frames, weldments and structures from plate, tube and structural shapes: cuts and fits the pieces to the print, tacks and welds them, and checks the result square and to size.'),
  (25, 'Laser Cutting Operator', 'fabrication', 'Runs CNC cutting tables (laser, plasma or waterjet): loads sheet or plate, calls up the nest, sets the cut for the material and thickness, and checks edge quality and size.'),
  (26, 'Stamping Press Operator', 'fabrication', 'Runs stamping presses that form sheet metal into panels and parts: feeds blanks or coil, watches the dies, and inspects and stacks the stampings.'),
  (27, 'Die Setter', 'fabrication', 'Changes dies in stamping presses: moves the die in by crane or cart, clamps and shuts it to height, threads the coil or sets the transfer, and runs first hits until the part is right.'),
  (28, 'Die Maintenance Technician', 'fabrication', 'Keeps stamping and casting dies running: pulls them for service, replaces worn details, welds and regrinds damage, spots the die back in and proves it in the press.'),
  (29, 'Die Casting Machine Operator', 'fabrication', 'Runs high-pressure die casting machines: tends the melt and the shot, sprays the die, pulls and trims the casting and checks it for defects.'),
  (30, 'Die Casting Technician', 'fabrication', 'Sets up die casting cells and keeps them in process: changes dies, sets shot, vacuum and spray, and troubleshoots porosity, cold shuts and sticking.'),
  (31, 'Casting Process Engineer', 'fabrication', 'Owns a casting process: designs gating and process windows, runs trials, reads X-ray and section results, and drives scrap down.'),
  (32, 'Injection Molding Operator', 'fabrication', 'Runs injection molding machines that make plastic parts: starts and monitors the press, clears and inspects parts, trims gates and keeps the cell supplied.'),
  (33, 'Additive Manufacturing Technician', 'fabrication', 'Runs metal and polymer 3D printers: prepares the build, handles powder or resin safely, tends the machine, and removes, cleans and finishes the parts.'),
  (34, 'Additive Manufacturing Engineer', 'fabrication', 'Develops printed parts and the process that makes them: redesigns for additive, sets orientation, supports and parameters, and qualifies the result through heat treatment and inspection.'),
  (35, 'Laser Technician', 'fabrication', 'Operates, aligns and services industrial laser systems used for cutting, welding, marking and measurement, and keeps their optics, chillers and safety interlocks in order.'),
  (36, 'Plastics Extrusion Operator', 'fabrication', 'Runs the extrusion lines that make plastic film, sheet, pipe, profile and compounded pellets, and the thermoforming lines that form sheet into cups, trays and parts: keeps resin dried and fed, watches barrel and die temperatures, melt pressure and line speed, checks gauge and dimensions, and winds, cuts, trims or packs the product.'),
  (37, 'Rubber Molding Operator', 'fabrication', 'Makes rubber goods and tire components: mixes and mills the compound, forms it by extruder or calender, vulcanizes it in compression, transfer, injection or tire curing presses, and deflashes and checks what comes out.'),
  (38, 'Plastics Process Technician', 'fabrication', 'Sets up and dials in plastics processes (injection molding, extrusion, blow molding, thermoforming): hangs molds and changes dies and screws, brings a new job to good product, and finds the cause of a defect in the process data rather than by chasing settings.'),
  (39, 'Blow Molding Operator', 'fabrication', 'Runs blow molding machines that make bottles, jugs, tanks and hollow parts from an extruded parison or a reheated preform: keeps material fed, watches heats, parison and blow pressures, checks weight, wall and top load, and clears, packs and palletizes the line.'),
  (40, 'Tire Builder', 'fabrication', 'Builds green tires on a tire building machine from inner liner, body plies, beads, belts and tread, placing, splicing and stitching each component to the specification at rate, ready for the curing press.'),
  (41, 'Converting Machine Operator', 'fabrication', 'Sets up and runs the machines that turn paper and paperboard into products: die cutters, folder gluers, flexo folder gluers, slitter rewinders, sheeters, and bag and cup machines. Makes ready each order, holds cut, fold and glue quality at speed and changes over to the next.'),
  (42, 'Corrugator Operator', 'fabrication', 'Runs the corrugator that makes corrugated board from rolls of liner and medium: the starch kitchen, roll stands and single facers at the wet end, and the double backer, slitter-scorer and knife at the dry end. Holds bond, caliper and warp through order changes made on the fly.'),
  (43, 'Bindery Operator', 'fabrication', 'Turns printed sheets into finished pieces: cuts on the guillotine, folds, stitches and binds, and die-cuts, foil-stamps and embosses. Sets each machine to the job and checks the work as it runs.'),
  (44, 'Dental Laboratory Technician', 'fabrication', 'Makes crowns, bridges, implant restorations and dentures to a dentist''s prescription: prepares models, designs in dental CAD, mills, prints or casts the restoration and layers and fires porcelain to match the patient''s teeth.'),
  (45, 'Sign Fabricator', 'fabrication', 'Builds signs in a sign plant: cuts and routes faces and cabinets, bends and assembles channel letters, welds and paints, prints and applies graphics, and wires the lighting so the sign can be listed and installed.'),
  (46, 'Ophthalmic Laboratory Technician', 'fabrication', 'Makes prescription spectacle lenses in an optical laboratory: surfaces the prescription into a lens blank, coats it, edges it to the frame and mounts it, and verifies the finished pair against the prescription.'),
  (47, 'Bench Jeweler', 'fabrication', 'Makes and repairs jewelry at the bench: cleans up castings, fabricates, solders and sizes in gold, platinum and silver, sets stones, laser welds and polishes and plates the finished piece.'),
  (48, 'Rolling Mill Operator', 'fabrication', 'Runs the mills that roll steel, aluminum and copper into plate, sheet, strip, bar, rod and shapes, and the lines that roll strip into profiles and welded tube: threads and sets the stands, watches gauge, shape and surface, and changes rolls and guides.'),
  (49, 'Casting Finisher', 'fabrication', 'Cleans castings after shakeout: cuts off gates and risers, gouges and grinds them to contour, blasts off the sand, and weld-repairs the defects inspection finds.'),
  (50, 'Glass Fabricator', 'fabrication', 'Turns flat glass into finished pieces and units: cuts it on CNC tables, edges and drills it, tempers or laminates it and builds insulating glass units, checking each piece for size and defects.'),
  (51, 'Foundry Molder', 'fabrication', 'Makes the sand molds and cores castings are poured in, by hand, on molding machines or on an automatic line, and the ceramic shells of investment casting: keeps the sand right, sets cores, closes the molds and sends them to pour.'),
  (52, 'Melter', 'fabrication', 'Melts and refines metal for casting in a steel mill or a foundry: charges and runs the arc or induction furnace, samples and corrects chemistry and temperature, treats the metal in the ladle, keeps the linings and taps or pours.'),
  (53, 'Forge Operator', 'fabrication', 'Shapes metal on hammers, presses, upsetters, ring mills and cold headers: heats the stock, forges it in open or impression dies, sets the dies, and checks the forgings or fasteners to the drawing.'),
  (54, 'Extrusion Press Operator', 'fabrication', 'Runs an aluminum extrusion press and its line: heats billets, changes and preheats dies, sets ram speed and temperatures, pulls, quenches, stretches and saws the profile, and checks it to the drawing.'),
  (55, 'Caster Operator', 'fabrication', 'Casts liquid metal into slabs, blooms, billets or ingots on a steel continuous caster or an aluminum direct-chill casting pit: prepares the tundish or table, opens the ladle, holds mold level, speed and cooling, and cuts, marks and checks the product.'),
  (56, 'Glass Forming Operator', 'fabrication', 'Runs the individual-section machines that blow bottles and jars from molten glass: sets the feeder and section timing, swabs and changes molds, corrects forming defects and makes the job changes.'),
  (57, 'Shipfitter', 'fabrication', 'Builds a ship''s steel or aluminum structure: lays out plate and shapes from the drawings, fits frames, stiffeners and bulkheads into units and blocks, tacks them for the welders, and takes out distortion with heat.'),
  (58, 'Pipefitter', 'fabrication', 'Fabricates, installs and tests piping systems in a ship, a factory or a process plant: lays out, cuts and bends pipe, fits and tacks it for welding or brazes it, makes up flanges and fittings, hangs it, and proves it by hydrostatic test.'),
  (59, 'Brazer', 'fabrication', 'Joins copper, brass, steel and aluminum tubing and parts by torch, induction or furnace brazing on a production line, mostly the refrigerant circuits of air conditioners, refrigerators and heat exchangers: fits and cleans the joint, brazes it under a nitrogen purge, and proves the circuit tight by pressure and leak test.'),
  (60, 'Wire and Cable Operator', 'fabrication', 'Makes wire and cable: draws steel, copper or aluminum rod down to wire, anneals it, strands and bunches it into conductors, extrudes insulation and jacket over it, cables the conductors together and takes the finished wire or cable up on reels, holding size, temper, concentricity and the spark test.'),
  (61, 'Welding Engineer', 'fabrication', 'Decides how a weld is made and proves it: develops and qualifies the welding procedure, sets parameters and fixturing for manual and automated processes, reads the test and inspection results, and finds the cause when welds fail.'),
  (62, 'Heat Treat Operator', 'materials', 'Runs furnaces that harden, temper, anneal and age metal parts: loads to the recipe, watches time, temperature and atmosphere, quenches, and checks hardness.'),
  (63, 'Plating and Anodizing Technician', 'materials', 'Runs chemical finishing lines: racks and masks parts, takes them through cleaning, plating, anodizing, conversion coating or passivation tanks, and checks thickness and adhesion.'),
  (64, 'Thermal Spray Technician', 'materials', 'Applies sprayed metal and ceramic coatings (plasma, HVOF) to engine and landing-gear parts: masks, grit-blasts, sprays by robot or by hand, and proves the coating. Often runs shot peening too.'),
  (65, 'Industrial Painter', 'materials', 'Prepares and coats manufactured parts: cleans and masks, mixes the coating, sprays liquid paint or powder, cures it, and checks film thickness and finish.'),
  (66, 'Aircraft Painter', 'materials', 'Strips, masks, primes and paints aircraft and aerospace parts to the specification, by hand spray in a hangar or booth, including liveries and specialty coatings.'),
  (67, 'Automotive Paint Technician', 'materials', 'Works a vehicle paint shop from bare body to finished color: pretreatment and e-coat, seam sealing, primer, base and clear in the booths, then inspection, sanding, polishing and spot repair.'),
  (68, 'Paint Process Engineer', 'materials', 'Owns a paint shop''s processes: bath chemistry, robot programs and booth balance, cure windows, film build and appearance, and the fight against dirt and defects.'),
  (69, 'Composite Technician', 'materials', 'Makes composite parts: cuts and kits plies, lays them up on the tool by hand, bags and cures the part, then trims and drills it.'),
  (70, 'Automated Fiber Placement Operator', 'materials', 'Runs the CNC machines that lay composite tape and tow onto a tool: loads material, starts and watches the program, and inspects each ply for gaps, laps and wrinkles.'),
  (71, 'Autoclave Operator', 'materials', 'Loads, instruments and runs autoclaves and ovens that cure composite and bonded parts, watching temperature, pressure and vacuum against the cure recipe.'),
  (72, 'Composite Bonding Technician', 'materials', 'Bonds composite and metal structure with film and paste adhesives: prepares the surfaces, fits core and details, bags and cures the assembly, and checks the bond line.'),
  (73, 'Composite Repair Technician', 'materials', 'Repairs damaged composite structure to the repair manual: maps the damage, dries and scarfs it, lays in the repair plies, cures them with a heat blanket and inspects the result.'),
  (74, 'Materials Testing Technician', 'materials', 'Tests metals and coatings in the laboratory or on the floor: hardness, tensile, metallographic sections, alloy identification, and reports against the specification.'),
  (75, 'Materials Engineer', 'materials', 'Chooses and qualifies the materials and special processes a product depends on, sets the specifications, and investigates when a material fails.'),
  (76, 'Printing Press Operator', 'materials', 'Makes ready and runs printing presses (offset, flexographic, digital or screen) on paper, board, labels and film. Brings color and register to the approved proof and holds them through the run.'),
  (77, 'Prepress Technician', 'materials', 'Gets a job ready for press: checks and imposes the customer''s files, makes the proofs and the printing plates (offset or flexographic), and keeps prepress, proof and press on one color standard.'),
  (78, 'Furniture Finisher', 'materials', 'Finishes wood furniture, cabinets and millwork: sands, stains, glazes and tones to a master color, sprays sealers and topcoats or runs the flatline, and repairs finish damage so it cannot be seen.'),
  (79, 'Textile Machine Operator', 'materials', 'Tends the machines that turn fiber into yarn and yarn into fabric: spinning frames, winders, looms, knitting, tufting and braiding machines and nonwoven lines. Pieces up broken ends, keeps the machines fed and running and catches defects before they spread.'),
  (80, 'Dyeing and Finishing Operator', 'materials', 'Dyes and finishes fiber, yarn, fabric or carpet: weighs dyes and chemicals to the recipe, runs dyeing machines and ranges and the tenters, compactors and coating lines after them, and checks shade, width and shrinkage before the goods move on.'),
  (81, 'Textile Colorist', 'materials', 'Works out and approves the dye recipes of a dye house: matches customer standards in the color laboratory by spectrophotometer and lab dip, scales recipes to production, approves production lots for shade and runs the laboratory''s colorfastness and physical tests.'),
  (82, 'Production Assembler', 'assembly', 'Puts components together into products at a bench or on a line, following work instructions with hand and power tools, and checks each unit before it moves on.'),
  (83, 'Precision Assembly Technician', 'assembly', 'Assembles close-tolerance mechanisms and instruments from drawings: fits bearings and shafts, shims and aligns, torques to sequence and measures as the build goes.'),
  (84, 'Machine Builder', 'assembly', 'Builds machinery from castings and components: scrapes and fits ways, installs spindles, ballscrews and guides, plumbs hydraulics and pneumatics, aligns the geometry and runs the machine off.'),
  (85, 'Automotive Assembler', 'assembly', 'Builds vehicles on a general assembly line: installs trim, wiring, cockpit, glass, seats, chassis and powertrain at a station, to takt time and torque specification.'),
  (86, 'Body Fit Technician', 'assembly', 'Hangs and fits doors, hoods, fenders and lids on a vehicle body, setting gaps and flushness to specification, and finishes out dings and surface defects in the metal.'),
  (87, 'Powertrain Assembler', 'assembly', 'Assembles engines, transmissions and electric drive units: fits bearings, gears, shafts and seals, torques in sequence, and passes each unit through leak and end-of-line test.'),
  (88, 'Aircraft Structures Mechanic', 'assembly', 'Builds airframes: locates and drills parts in the jig, installs rivets and other fasteners, seals, shims and joins panels, frames and major sections to the drawing.'),
  (89, 'Aircraft Systems Mechanic', 'assembly', 'Installs and rigs the systems inside an airframe during final assembly: hydraulics, fuel, flight controls, landing gear, environmental and oxygen systems, then tests them working.'),
  (90, 'Rocket Engine Technician', 'assembly', 'Builds liquid rocket engines: assembles turbopumps, valves, injectors and chambers in clean conditions, torques and safety-wires, leak-checks, and readies the engine for hot fire.'),
  (91, 'Propulsion Technician', 'assembly', 'Installs propulsion on launch vehicles and spacecraft: engines and thrusters, thrust-vector actuators, propellant tanks, pressurant bottles, valves and tubing, then leak-checks the system.'),
  (92, 'Launch Vehicle Integration Technician', 'assembly', 'Assembles and integrates rocket stages: joins tank and structure sections, installs fairings, interstages, landing and separation mechanisms and heat shielding, and refurbishes recovered boosters.'),
  (93, 'Spacecraft Integration Technician', 'assembly', 'Assembles satellites and spacecraft in a cleanroom: builds the bus, installs solar arrays, antennas, mechanisms, harness and thermal blankets, and supports the spacecraft through test.'),
  (94, 'Missile and Ordnance Technician', 'assembly', 'Assembles and tests missiles and munitions: builds up airframes, installs guidance sections, motors, warheads and initiators under explosive-safety rules, and runs acceptance tests.'),
  (95, 'Medical Device Assembler', 'assembly', 'Assembles medical devices (catheters, implants, instruments, pumps) by hand and under a microscope in a controlled room, to documented procedures and with full lot records.'),
  (96, 'Truss Builder', 'assembly', 'Builds roof and floor trusses and wall panels in a component plant: cuts members on the component saw, sets the table''s jigs to the truss drawing, and places and presses the connector plate at each joint.'),
  (97, 'Cabinetmaker', 'assembly', 'Builds cabinets, casework, millwork and furniture from shop drawings: machines parts, joins and assembles them, veneers and laminates, fits hardware and finishes. The bench trade of a cabinet or furniture plant.'),
  (98, 'Upholsterer', 'assembly', 'Builds and covers upholstered furniture: installs springs and webbing, shapes foam and padding, cuts and sews covers, and fits them to the frame smooth and square.'),
  (99, 'Sewing Machine Operator', 'assembly', 'Sews the cut pieces of garments and other sewn products together on industrial sewing machines, one operation or the whole piece, to the tech pack, and checks the work before it moves on.'),
  (100, 'Medical Device Manufacturing Technician', 'assembly', 'Builds the harder subassemblies of medical devices and keeps their processes running in a controlled room: sets up and proves bonding, reflow, welding and sealing equipment, runs qualification protocols, troubleshoots and trains assemblers.'),
  (101, 'Fabric Cutter', 'assembly', 'Cuts fabric and leather into the pieces of sewn products: spreads and lays up cloth to the marker or reads hides for flaws, cuts by knife, die or automated cutter, and bundles and tickets the pieces for the sewing floor.'),
  (102, 'Shoemaker', 'assembly', 'Builds shoes and boots in a footwear plant: cuts leather, lasts the stitched upper, attaches the bottom by welt, stitchdown or cement, and finishes the shoe.'),
  (103, 'RV Assembler', 'assembly', 'Builds recreational vehicles on a moving line: laminates the walls and roof, lays the roof membrane, installs the plumbing, propane and 12- and 120-volt wiring, sets the cabinets and interior, and water-tests the unit.'),
  (104, 'Electronics Assembler', 'electronics', 'Builds electronic assemblies by hand: places and solders components, fits boards, cables and hardware into the enclosure, and inspects the work to IPC standards.'),
  (105, 'SMT Line Operator', 'electronics', 'Runs a surface-mount line: sets up the paste printer, pick-and-place and reflow oven, loads feeders, and works the inspection machines that follow.'),
  (106, 'PCB Rework Technician', 'electronics', 'Repairs circuit boards that fail inspection or test: removes and replaces components down to fine-pitch and BGA, repairs pads and traces, and proves the joint by X-ray.'),
  (107, 'Electronics Technician', 'electronics', 'Troubleshoots and repairs electronic equipment to component level with schematics, meter and oscilloscope, and builds and modifies prototypes for engineers.'),
  (108, 'Wire Harness Assembler', 'electronics', 'Builds wire harnesses and cable assemblies on a form board: cuts, strips and crimps, pins connectors, laces and labels, and tests every circuit.'),
  (109, 'Electrical Panel Builder', 'electronics', 'Builds and wires control panels, motor control centers and switchgear from schematics: lays out and mounts devices, runs wire and bus, terminates, labels and tests.'),
  (110, 'Aircraft Electrician', 'electronics', 'Installs the electrical system in an aircraft: routes and clamps harnesses, terminates and pins connectors, bonds and grounds, installs power distribution, and rings out every circuit.'),
  (111, 'Avionics Technician', 'electronics', 'Installs, tests and troubleshoots an aircraft''s electronics (navigation, communication, displays, flight management, radar and data buses) on the production line or in maintenance.'),
  (112, 'Power Electronics Technician', 'electronics', 'Builds inverters, converters, chargers and power modules: mounts power devices and busbars, applies thermal interface and potting, assembles the cooling, and runs high-voltage tests.'),
  (113, 'Server Assembly Technician', 'electronics', 'Builds servers and racks: installs boards, processors, memory, drives and cooling, cables the rack, loads firmware and the operating system, and runs burn-in.'),
  (114, 'Consumer Electronics Assembler', 'electronics', 'Assembles phones, tablets, laptops and wearables on a high-volume line: fits displays, batteries, cameras and sensors, seals the enclosure and runs the station''s test.'),
  (115, 'Marine Electrician', 'electronics', 'Wires ships and boats: pulls and bands cable through the hull, takes it through stuffing tubes and cable transits, terminates and tests it, and installs power distribution, lighting and equipment, from a ship''s three-phase power to a boat''s DC system.'),
  (116, 'Transformer Assembler', 'electronics', 'Builds distribution and power transformers: winds the coils, stacks the core, assembles core and coil, connects the leads and tap changer, dries and tanks the unit, fills it with oil and runs its routine tests.'),
  (117, 'PCB Fabrication Technician', 'electronics', 'Makes bare printed circuit boards: images the copper layers, etches and plates them, presses multilayer stacks, drills and routes the panels, and tests every net for opens and shorts.'),
  (118, 'Optical Technician', 'electronics', 'Builds, aligns and tests optical and electro-optical assemblies (lenses, mirrors, lasers, sensors and fiber), and in an optics shop grinds and polishes the optics themselves.'),
  (119, 'Wafer Fab Operator', 'semiconductor', 'Moves wafer lots through a fab: gowns in, loads tools, runs the recipe the system calls for, logs the lot and flags anything out of control.'),
  (120, 'Lithography Process Technician', 'semiconductor', 'Runs and sustains the photolithography area: coat and develop tracks, steppers and scanners, reticles, and the focus, dose and overlay checks that keep the pattern in specification.'),
  (121, 'Etch Process Technician', 'semiconductor', 'Runs and sustains plasma etch and strip tools: monitors etch rate, endpoint and profile, qualifies chambers after maintenance and responds to excursions.'),
  (122, 'Thin Film Process Technician', 'semiconductor', 'Runs and sustains deposition tools (CVD, ALD, PVD, epitaxy, plating) and checks every film for thickness, stress and particles.'),
  (123, 'Diffusion and Implant Process Technician', 'semiconductor', 'Runs and sustains furnaces, rapid thermal tools and ion implanters: oxidation, anneal and doping, with the sheet-resistance and thickness monitors that prove them.'),
  (124, 'Wet Process and CMP Technician', 'semiconductor', 'Runs and sustains wet benches, cleans and chemical mechanical polishers: bath chemistry, etch and removal rates, and the defects they leave.'),
  (125, 'Semiconductor Metrology Technician', 'semiconductor', 'Measures and inspects wafers in line: critical dimension, overlay, film thickness and defects, and reviews and classifies what the inspection tools find.'),
  (126, 'Semiconductor Equipment Technician', 'semiconductor', 'Installs, maintains and repairs wafer fab tools, in a fab or as the toolmaker''s field service engineer: preventive maintenance, vacuum and gas systems, robots, and fault finding to get a tool back up.'),
  (127, 'Semiconductor Equipment Engineer', 'semiconductor', 'Owns a fleet of fab tools: availability, maintenance procedures, chamber matching, upgrades, and the root cause when a tool drifts or goes down.'),
  (128, 'Lithography Process Engineer', 'semiconductor', 'Develops and controls patterning: resist and exposure processes, focus and dose windows, overlay and critical dimension control, and the corrections applied to the mask.'),
  (129, 'Etch Process Engineer', 'semiconductor', 'Develops and controls plasma etch processes: chemistry, selectivity, profile and uniformity, chamber matching, and the experiments that widen the window.'),
  (130, 'Thin Film Process Engineer', 'semiconductor', 'Develops and controls deposition processes (CVD, ALD, PVD, epitaxy, metal fill): film properties, uniformity, defects and the recipes that deliver them.'),
  (131, 'Diffusion and Implant Process Engineer', 'semiconductor', 'Develops and controls thermal and doping processes: oxidation, anneal, rapid thermal processing and ion implantation, and the junctions and films they form.'),
  (132, 'Wet Process and CMP Engineer', 'semiconductor', 'Develops and controls wet cleans, wet etch and chemical mechanical planarization: chemistries, slurries and pads, removal rates, and defect reduction.'),
  (133, 'Process Integration Engineer', 'semiconductor', 'Owns the whole process flow for a technology: how the modules fit together, what the electrical results say about them, and which change fixes a device or yield problem.'),
  (134, 'Yield Engineer', 'semiconductor', 'Finds what is killing die: reads wafer maps, inline defect and electrical test data, traces the loss to a tool or step, and drives the fix.'),
  (135, 'Failure Analysis Technician', 'semiconductor', 'Prepares and examines failed devices and material samples in the laboratory: cross-sections, electron microscopy and surface analysis, with a report of what was found.'),
  (136, 'Failure Analysis Engineer', 'semiconductor', 'Leads the investigation of a device failure: isolates the fault electrically, directs the physical analysis, names the mechanism and the corrective action.'),
  (137, 'Semiconductor Packaging Technician', 'semiconductor', 'Runs back-end assembly: dicing, die attach, wire or flip-chip bonding, underfill, molding and marking, with the pull and shear tests that prove each bond.'),
  (138, 'Semiconductor Packaging Engineer', 'semiconductor', 'Develops how a chip is packaged: package design and materials, the assembly process, and its reliability through qualification.'),
  (139, 'Semiconductor Test Technician', 'semiconductor', 'Runs wafer probe and final test: sets up probers, handlers and testers, loads the test program, keeps the cell yielding, and sorts good die from bad.'),
  (140, 'Semiconductor Test Engineer', 'semiconductor', 'Writes and maintains the test programs and hardware that decide whether a chip ships: coverage, limits, test time and correlation between testers.'),
  (141, 'Battery Electrode Technician', 'battery', 'Makes battery electrodes: mixes the slurry, coats it onto foil, dries, calenders and slits it, and controls loading, thickness and defects along the way.'),
  (142, 'Battery Cell Assembly Technician', 'battery', 'Assembles battery cells in a dry room: winds or stacks electrodes and separator, welds tabs, inserts the roll in the can, fills electrolyte and seals the cell.'),
  (143, 'Battery Cell Formation Technician', 'battery', 'Brings new cells to life: runs formation cycling, degassing and aging, watches voltage for rejects, and grades cells by capacity.'),
  (144, 'Battery Pack Assembly Technician', 'battery', 'Builds cells into modules and packs: welds interconnects and busbars, installs the management system, high-voltage harness and cooling, seals the enclosure and runs leak and end-of-line tests.'),
  (145, 'Battery Cell Engineer', 'battery', 'Develops cells and the process that makes them: electrode design and materials, the coating, assembly and formation windows, and the tests that show a change is better.'),
  (146, 'Battery Pack Engineer', 'battery', 'Designs battery modules and packs: structure, sealing, cooling, high-voltage layout and the management system''s hardware, through to validation.'),
  (147, 'Electric Motor Assembler', 'battery', 'Builds electric motors: winds or inserts the stator conductors, welds and impregnates them, fits magnets to the rotor, balances it, and assembles the motor in its housing.'),
  (148, 'Food Processing Operator', 'process', 'Makes food to the recipe: weighs and blends the batch, runs the cooking, forming, drying or sterilising equipment, and keeps the line clean and its safety records true.'),
  (149, 'Beverage Production Operator', 'process', 'Runs a bottling or canning line: prepares the syrup, carbonates, fills and seams or caps, and checks fill, Brix and closures through the shift.'),
  (150, 'Packaging Line Operator', 'process', 'Runs the machines that fill, close, label, case and palletize product, clears jams, changes the line over between sizes and checks codes and weights.'),
  (151, 'Chemical Operator', 'process', 'Runs chemical and compounding processes: charges raw materials, controls reactors, mixers and transfers from the board and the floor, samples the batch and handles hazardous materials safely.'),
  (152, 'Pharmaceutical Manufacturing Operator', 'process', 'Makes tablets and capsules under GMP: dispenses and blends, granulates, compresses or fills, coats, and records every step in the batch record.'),
  (153, 'Aseptic Filling Technician', 'process', 'Fills sterile drug product into vials and syringes in a classified cleanroom or isolator: gowns to qualification, sets up the line aseptically, runs filling and freeze drying, and monitors the room.'),
  (154, 'Sterilization Technician', 'process', 'Runs the sterilizers that medical devices and drug components pass through (steam, ethylene oxide), loads to the validated pattern and releases each cycle on its records.'),
  (155, 'Quality Control Chemist', 'process', 'Tests raw materials, in-process samples and finished product in the laboratory by chromatography, dissolution and titration, and releases or rejects on the result.'),
  (156, 'Quality Control Microbiologist', 'process', 'Tests product, water and the manufacturing environment for microbial contamination: bioburden, sterility and endotoxin, with the room and personnel monitoring behind them.'),
  (157, 'Process Engineer', 'process', 'Owns a production process in a chemical, food, pharmaceutical or materials plant: sets its conditions, studies its variation, scales it up and validates each change.'),
  (158, 'Meat Cutter', 'process', 'Breaks chilled beef, pork, lamb or poultry carcasses into cuts on a plant''s fabrication floor, then bones and trims them to the customer''s specification with a knife, a powered trimmer and a band saw, at line speed.'),
  (159, 'Slaughterer', 'process', 'Works the harvest floor of a meat or poultry plant: moves and stuns the animals humanely, bleeds, dresses and eviscerates the carcass, splits it and trims it clean, and sends it washed to the cooler.'),
  (160, 'Baker', 'process', 'Makes bread, buns, cakes, cookies or crackers at production scale: scales and mixes the dough to temperature, ferments and proofs it, runs the make-up line and the oven to the bake profile, and judges each stage by eye and hand.'),
  (161, 'Sanitation Technician', 'process', 'Cleans and sanitizes a food plant''s production equipment between runs and through the night: locks out and takes the line apart, dry-cleans, foams, scrubs, rinses and sanitizes it to the written procedure, reassembles it and has it inspected before production starts.'),
  (162, 'Food Safety and Quality Technician', 'process', 'Checks a food plant''s product and process through the shift: verifies the critical control points and the pre-operational clean, swabs the environment, tests samples for weight, pH, moisture and taste, checks labels and codes, and holds what does not meet the specification.'),
  (163, 'Brewer', 'process', 'Makes beer from grain to bright tank: mills and mashes the grain, lauters and boils the wort with hops, pitches and manages the yeast through fermentation and conditioning, and filters, carbonates and checks the beer before it is packaged.'),
  (164, 'Winemaker', 'process', 'Makes wine in a winery''s cellar, from the grapes to the bottle: receives, crushes and presses the fruit, manages the fermentations, racks, tops and ages the wine in tank and barrel, fines and filters it, tests it in the lab and blends it for bottling.'),
  (165, 'Grain Miller', 'process', 'Runs a flour, corn, rice or feed mill: receives, cleans and tempers the grain, sets the roller mills and sifters, or the hammer mills and pellet mills, to the flow, checks the product''s moisture, ash and protein, and keeps the dust and the bins safe.'),
  (166, 'Food Safety Specialist', 'process', 'Owns a food plant''s food safety system: writes and reassesses the HACCP and preventive-controls plans, runs the environmental monitoring, allergen, sanitation and supplier programs, leads the certification and regulatory audits, and investigates every deviation and recall.'),
  (167, 'Food Scientist', 'process', 'Develops a food company''s products and keeps them right: formulates new products and reformulates old ones, scales them from the bench to the plant, runs the sensory panels and shelf-life studies, and writes the specification and the label.'),
  (168, 'Cheesemaker', 'process', 'Makes cheese from milk: receives and standardizes the milk, pasteurizes it, sets it with culture and rennet, cuts, cooks and drains the curd, salts, moulds and presses it, and brines and ages it to grade.'),
  (169, 'Distiller', 'process', 'Makes spirits: cooks and mashes the grain, ferments it, runs the pot or column stills and makes the cuts, fills and ages the spirit in barrels, and proofs, blends and gauges it for bottling.'),
  (170, 'Chemical Laboratory Technician', 'process', 'Tests raw materials, process samples and finished product in a chemical, refinery or resin plant laboratory, by titration and physical tests, chromatography and spectroscopy, and reports the results the plant runs and ships on.'),
  (171, 'Biomanufacturing Technician', 'process', 'Makes biologic drugs (antibodies, proteins, vaccines) under GMP: prepares media and buffers, grows cells or microbes in bioreactors, harvests and purifies the product by centrifuge, filtration and chromatography, and keeps the equipment clean, sterile and on its batch record.'),
  (172, 'Refinery Operator', 'process', 'Runs a refinery''s process units (crude distillation, hydrotreating, reforming, catalytic cracking and the tank farm) from the field and the control room: makes rounds, lights and holds fired heaters, starts compressors and pumps, takes samples and keeps the unit on specification.'),
  (173, 'Validation Specialist', 'process', 'Proves that a drug or medical device plant''s equipment, cleaning and sterilization do what they claim: writes and executes qualification protocols (IQ, OQ, PQ), maps temperatures, samples for cleaning residues, and reports results and deviations.'),
  (174, 'Paper Machine Operator', 'process', 'Runs a paper, board or tissue machine as one of its crew, from stock preparation through the wet end, dryers and calender to the reel and winder. Rises from fifth hand to back tender and machine tender, who answers for the sheet''s weight, moisture, strength and every break.'),
  (175, 'Pulp Mill Operator', 'process', 'Runs the fiber line and chemical recovery of a kraft pulp mill from the control room and the floor: the digesters, washers and bleach plant, the evaporators, recausticizing and lime kiln, and at the top the recovery boiler.'),
  (176, 'Engineered Wood Operator', 'process', 'Runs the lines that make plywood, LVL, OSB, particleboard and MDF: veneer lathes and dryers, resin blenders, layup and mat forming, and the hot press. Holds moisture, resin, weight and bond to each panel''s grade.'),
  (177, 'Mineral Kiln Operator', 'process', 'Runs the kilns of a cement, lime, brick, refractory or ceramics plant, and the mills that grind for them: holds feed, fuel, flame and draft, or the firing curve, so the clinker, lime or ware comes out right.'),
  (178, 'Quality Control Inspector', 'quality', 'Checks parts and products against the drawing at receiving, in process, at first article and before shipping, with hand gauges and bench instruments, and writes up what does not conform.'),
  (179, 'CMM Programmer', 'quality', 'Measures parts on a coordinate measuring machine: aligns the part to its datums, writes and runs the measurement program from the drawing''s GD&T, and reports the results.'),
  (180, 'Dimensional Metrology Technician', 'quality', 'Measures large and complex shapes (vehicle bodies, airframe tooling, castings) with laser trackers, scanners and portable arms, and turns the data into a report the build can act on.'),
  (181, 'Calibration Technician', 'quality', 'Calibrates a plant''s measuring instruments (gauges, torque tools, pressure and temperature devices, electrical meters) against traceable standards and keeps their records.'),
  (182, 'Metrology Engineer', 'quality', 'Decides how a product will be measured: chooses the method and equipment, proves the measurement system is capable, and states its uncertainty.'),
  (183, 'Aircraft Assembly Inspector', 'quality', 'Inspects aircraft as they are built: fastener and sealant workmanship, installations and rigging, closeout of each zone, witnessed functional tests, and the records that make the aircraft conform.'),
  (184, 'Vehicle Final Inspector', 'quality', 'Checks finished vehicles at the end of the line: fit and finish, roll and brake test, wheel alignment, headlamp aim, driver-assistance calibration, water test and a short drive for noises.'),
  (185, 'Quality Engineer', 'quality', 'Builds quality into a product and process: control plans and FMEAs, capability studies, supplier approval, and the root cause and corrective action when something escapes.'),
  (186, 'Lumber Grader', 'quality', 'Grades every board for its value by eye, to a grading agency''s rules or the hardwood association''s, at the planer or the green chain, and oversees the scanners that grade automatically.'),
  (187, 'NDT Technician (Penetrant)', 'ndt', 'Finds surface cracks with liquid penetrant: cleans the part, applies penetrant and developer by the method the specification calls for, and reads the indications under white or UV light.'),
  (188, 'NDT Technician (Magnetic Particle)', 'ndt', 'Finds surface and near-surface cracks in steel parts by magnetising them and applying particles, choosing the technique and current, then demagnetising.'),
  (189, 'NDT Technician', 'ndt', 'Inspects parts and welds for hidden flaws without damaging them, certified in several methods: usually visual, penetrant and magnetic particle, with a volumetric method added.'),
  (190, 'NDT Technician (Ultrasonic)', 'ndt', 'Finds internal flaws and measures thickness with ultrasound: calibrates on reference blocks, scans by contact or immersion, sizes what it finds, and moves on to phased array.'),
  (191, 'NDT Technician (Radiographic)', 'ndt', 'Images the inside of castings, welds and assemblies with X-ray, by film, digital detector or CT, sets the exposure safely and interprets the image.'),
  (192, 'NDT Technician (Eddy Current)', 'ndt', 'Finds cracks and corrosion in conductive parts with eddy current probes: fastener holes, aircraft skins and tubing, and measures conductivity and coating thickness.'),
  (193, 'NDT Technician (Composites)', 'ndt', 'Inspects composite and bonded structure for delamination, disbond and porosity with ultrasonic C-scan, bond testers, tap test, shearography and thermography.'),
  (194, 'Test Technician', 'test', 'Tests finished assemblies and systems against their specification: sets up the fixture and instruments, runs functional, electrical and environmental tests, and diagnoses what fails.'),
  (195, 'RF Technician', 'test', 'Builds, tunes and tests radio-frequency hardware (radar, antennas, phased arrays, electronic warfare equipment) with network and spectrum analyzers.'),
  (196, 'Powertrain Test Technician', 'test', 'Tests motors, drive units, engines and transmissions at end of line or on a dynamometer: connects the unit, runs the cycle, reads noise, vibration and electrical results, and finds the cause of a failure.'),
  (197, 'Propulsion Test Technician', 'test', 'Operates engine test stands and cells: installs the engine, connects propellant and instrumentation, loads propellants, runs the firing or ground run from the console and inspects afterwards.'),
  (198, 'Launch Pad Technician', 'test', 'Maintains and operates a launch site''s ground systems: transporter-erector, umbilicals and quick-disconnects, propellant and gas systems, through rollout, loading and recovery.'),
  (199, 'Test Engineer', 'test', 'Decides how a product is proven to work and builds the means: test plans and limits, fixtures and automated test software, and the analysis of what fails and why.'),
  (200, 'Product Reliability Engineer', 'test', 'Shows how long a product will last: designs stress, burn-in and accelerated life tests, models the failures and works with design to remove the weak points.'),
  (201, 'Maintenance Technician', 'maintenance', 'Keeps a plant''s machines running: preventive maintenance, mechanical, hydraulic, pneumatic and basic electrical repair, and finding the fault when a line goes down.'),
  (202, 'Millwright', 'maintenance', 'Installs, moves, aligns and rebuilds heavy machinery: rigs it into place, levels and anchors it, aligns shafts and couplings, and overhauls gearboxes, pumps and conveyors.'),
  (203, 'Industrial Electrician', 'maintenance', 'Installs and maintains a plant''s electrical systems: power distribution, conduit and wiring, motors and their controls, and troubleshooting live equipment safely.'),
  (204, 'Hydraulics Technician', 'maintenance', 'Repairs and troubleshoots hydraulic and pneumatic systems and overhauls their components (pumps, cylinders, servo valves, accumulators) on the bench and on the machine.'),
  (205, 'Reliability Engineer', 'maintenance', 'Keeps plant equipment from failing: analyses breakdown history, sets the maintenance strategy, runs vibration, thermography and oil analysis programs, and leads root cause work on chronic failures.'),
  (206, 'Facilities Engineer', 'maintenance', 'Runs the utilities a plant depends on: power, compressed air, cooling and process water, bulk gases and chemicals, exhaust and waste treatment, and their capacity and reliability.'),
  (207, 'Aircraft Mechanic', 'maintenance', 'Inspects, services and repairs aircraft to the maintenance manual and signs for the work: airframe, systems and engines, on the flight line or in a repair station.'),
  (208, 'Aircraft Engine Mechanic', 'maintenance', 'Tears down, inspects, repairs and rebuilds turbine engines and their modules, accessories and propellers, balances the rotors and readies the engine for test.'),
  (209, 'Industrial Refrigeration Technician', 'maintenance', 'Runs and maintains the ammonia refrigeration plant that keeps a food or beverage plant''s rooms, freezers and process cold: compressors, condensers, vessels and defrost, the daily logs, draining oil and purging air, and the process safety work the ammonia requires.'),
  (210, 'Textile Machine Technician', 'maintenance', 'Sets up, times and repairs the machines of a textile or sewn-products plant: looms, knitting and tufting machines, spinning frames and industrial sewing machines. Changes machines over to a new style and finds why one keeps stopping or making defects.'),
  (211, 'Equipment Field Service Technician', 'maintenance', 'Installs, commissions and repairs a machine builder''s equipment at customers'' plants: sets and starts new machines, finds mechanical, hydraulic, electrical and control faults on site, does scheduled service and teaches the operators to run what was installed.'),
  (212, 'Railcar Mechanic', 'maintenance', 'Builds, rebuilds and repairs railcars: trucks and wheelsets, couplers and draft gear, air brakes and their single car test, and the welding and bolting of the car body.'),
  (213, 'Automation Technician', 'automation', 'Keeps automated cells running: robots, conveyors, pneumatics, sensors and vision, with enough PLC to follow the logic to the fault and make small changes.'),
  (214, 'Controls Technician', 'automation', 'Troubleshoots a plant''s electrical controls and instrumentation: goes online with the PLC, tunes drives, calibrates instruments and loops, and fixes the network when devices drop.'),
  (215, 'Robotics Technician', 'automation', 'Installs, maintains and recovers industrial and collaborative robots: mastering, tooling changes, touch-ups on the pendant, safeguarding and preventive maintenance.'),
  (216, 'Robot Programmer', 'automation', 'Writes and optimises robot programs for welding, handling, sealing and painting, at the pendant and offline in simulation, and commissions them in the cell.'),
  (217, 'Controls Engineer', 'automation', 'Designs and programs machine control systems: PLC and safety logic, operator screens, drives and motion, industrial networks, and the commissioning on site.'),
  (218, 'Automation Engineer', 'automation', 'Designs automated production systems: the cell concept, robots and tooling, vision and sensing, safety, and their integration with the line''s controls.'),
  (219, 'Manufacturing Engineer', 'engineering', 'Works out how a product is built: the process steps, tooling and work instructions, the line''s layout and capacity, and the fixes when it does not run to plan. Launches new products into production.'),
  (220, 'Mechanical Engineer', 'engineering', 'Designs mechanical parts and assemblies: models them in CAD, sizes them by calculation and analysis, tolerances the drawings, and sees the design through prototype and release.'),
  (221, 'Electrical Engineer', 'engineering', 'Designs electrical and electronic systems for products and equipment: power, circuits and boards, wiring and controls, and the tests that prove them.'),
  (222, 'Tooling Engineer', 'engineering', 'Designs the dies, molds, fixtures and gauges production needs, works with the toolroom to build them and proves them out on the floor.'),
  (223, 'CAD Designer', 'engineering', 'Turns an engineer''s concept into models and drawings: 3D parts and assemblies, detail drawings with dimensions and tolerances, and their revisions in the data system.'),
  (224, 'Systems Engineer', 'engineering', 'Holds a complex product together across disciplines: requirements and interfaces, how the subsystems integrate in the vehicle or spacecraft, and the verification that it all works.'),
  (225, 'Aerospace Engineer', 'engineering', 'Designs and analyses aircraft and spacecraft structures and components, and supports their build: stress and fatigue, materials, drawings, and disposition of nonconforming hardware.'),
  (226, 'Propulsion Engineer', 'engineering', 'Designs and develops engines and propulsion systems for aircraft and rockets, and proves them on the test stand: components, performance analysis and hot-fire data.'),
  (227, 'Automotive Engineer', 'engineering', 'Designs vehicle systems (body, chassis, powertrain) and tunes how they behave, from CAD and analysis through prototype builds and validation.'),
  (228, 'Biomedical Engineer', 'engineering', 'Designs medical devices and the evidence that they are safe: design controls, risk analysis, verification and validation under the medical device quality system.'),
  (229, 'Truss Designer', 'engineering', 'Lays out a building''s roof and floor trusses from its plans and designs each truss for its loads in truss design software, producing the placement plan for the builder and the cutting and table files for the plant.'),
  (230, 'Apparel Patternmaker', 'engineering', 'Makes and grades the patterns sewn products are cut from, lays out markers for the cutting room and corrects the patterns from fittings until the product fits and sews as specified.'),
  (231, 'Naval Architect', 'engineering', 'Designs ships and boats: hull form, structure, stability and weight, and the arrangement and production drawings a shipyard builds from; then supports the build, the inclining experiment and trials.');
